-- Data-independent production expression case normalization.
-- Policy: no-case locale prefixes are untouched; complete ASCII
-- all-uppercase expressions (for example UFO) are untouched.
-- langmap:batch
DROP TABLE IF EXISTS _lm_case_20260910_form_targets;
-- langmap:batch
DROP TABLE IF EXISTS _lm_case_20260910_edge_targets;
-- langmap:batch
DROP TABLE IF EXISTS _lm_case_20260910_map;
-- langmap:batch
DROP TABLE IF EXISTS _lm_case_20260910_keys;
-- langmap:batch
DROP TABLE IF EXISTS _lm_case_20260910_policy;
-- langmap:batch
CREATE TABLE _lm_case_20260910_policy (prefix TEXT PRIMARY KEY);
INSERT INTO _lm_case_20260910_policy(prefix) VALUES ('cmn-Hans'),('cmn-Hant'),('jpn'),('kor'),('nan-Hant');
-- langmap:batch
CREATE TABLE _lm_case_20260910_keys (expression_id INTEGER PRIMARY KEY,language_id INTEGER NOT NULL,homograph_index INTEGER NOT NULL,normalized_text TEXT NOT NULL);
CREATE INDEX _lm_case_20260910_keys_identity ON _lm_case_20260910_keys(language_id, homograph_index, normalized_text, expression_id);
-- langmap:batch
CREATE TABLE _lm_case_20260910_map (old_expression_id INTEGER PRIMARY KEY,survivor_expression_id INTEGER NOT NULL,target_text TEXT NOT NULL);
CREATE INDEX _lm_case_20260910_map_survivor ON _lm_case_20260910_map(survivor_expression_id);
-- langmap:batch
INSERT OR IGNORE INTO _lm_case_20260910_keys(expression_id,language_id,homograph_index,normalized_text) SELECT e.id,e.language_id,e.homograph_index,upper(substr(lower(trim(e.text)), 1, 1)) || substr(lower(trim(e.text)), 2) FROM expressions e WHERE e.id >= 1 AND e.id < 100001 AND trim(e.text) GLOB '[A-Za-z]*' AND trim(e.text) NOT GLOB '*[^ -~]*' AND NOT (trim(e.text) GLOB '*[A-Z]*' AND trim(e.text) NOT GLOB '*[a-z]*') AND EXISTS (SELECT 1 FROM expression_locale_links ell JOIN language_locales ll ON ll.id = ell.locale_id WHERE ell.expression_id = e.id AND NOT EXISTS (SELECT 1 FROM _lm_case_20260910_policy p WHERE ll.code LIKE p.prefix || '%'));
